(() => {"use strict";const root=document.documentElement;const key=v=>String(v||"").toLowerCase().replace(/[^a-z0-9]+/g,"-");async function load(){try{const r=await fetch("/api/method/qorg.qorg.design_system.api.get_effective_configuration");const c=(await r.json()).message||{};if(!c.enabled)return;root.dataset.qorgWebTheme="1";root.dataset.qorgMode=key(c.theme_mode);root.dataset.qorgDensity=key(c.density);Object.entries(c.tokens||{}).forEach(([k,v])=>root.style.setProperty(k,v));if(document.querySelector(".for-login")&&c.apply_to_login){root.dataset.qorgLoginLayout=key(c.login_layout);const card=document.querySelector(".for-login .page-card");if(card&&!card.querySelector(".qorg-login-visual")){const visual=document.createElement("aside");visual.className="qorg-login-visual";if(c.login_image)visual.style.backgroundImage=`url(${JSON.stringify(String(c.login_image))})`;visual.innerHTML=`<div><h2>${frappe.utils.escape_html(c.login_title||"")}</h2><p>${frappe.utils.escape_html(c.login_subtitle||"")}</p></div>`;card.append(visual);}}if(c.apply_to_web_forms){root.dataset.qorgWideWebForms=c.wide_web_forms?"1":"0";root.dataset.qorgStickyActions=c.sticky_mobile_actions?"1":"0";}}catch(e){console.warn("Q Org web theme unavailable",e)}}if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",load,{once:true});else load();})();
